import test from 'node:test';
import assert from 'node:assert/strict';
import { getCustomer, listCustomers, normalizeId, validateCustomer, mergeCustomers, TIER_DISCOUNTS } from '../src/customers.js';

test('getCustomer returns customer by id', () => {
  const result = getCustomer('C-001');

  assert.equal(result.ok, true);
  assert.equal(result.value.id, 'C-001');
  assert.equal(result.value.name, 'Northwind Studio');
});

test('getCustomer normalizes id', () => {
  const result1 = getCustomer('c-001');
  const result2 = getCustomer('C-001 ');

  assert.equal(result1.ok, true);
  assert.equal(result1.value.id, 'C-001');
  assert.equal(result2.ok, true);
  assert.equal(result2.value.id, 'C-001');
});

test('getCustomer returns CUSTOMER_NOT_FOUND for unknown id', () => {
  const result = getCustomer('UNKNOWN');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('getCustomer does not mutate the customer record', () => {
  const result = getCustomer('C-001');
  result.value.name = 'Modified';

  const result2 = getCustomer('C-001');
  assert.equal(result2.value.name, 'Northwind Studio');
});

test('listCustomers returns all customers', () => {
  const customers = listCustomers();

  assert(Array.isArray(customers));
  assert(customers.length > 0);
  assert(customers.some((c) => c.id === 'C-001'));
});

test('listCustomers does not mutate original data', () => {
  const customers1 = listCustomers();
  customers1[0].name = 'Modified';

  const customers2 = listCustomers();
  assert.equal(customers2[0].name, 'Northwind Studio');
});

test('normalizeId trims and uppercases', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
  assert.equal(normalizeId('C-001 '), 'C-001');
  assert.equal(normalizeId(' c-001 '), 'C-001');
  assert.equal(normalizeId('  C-001  '), 'C-001');
});

test('TIER_DISCOUNTS has expected values', () => {
  assert.equal(TIER_DISCOUNTS.gold, 5);
  assert.equal(TIER_DISCOUNTS.silver, 2.5);
  assert.equal(TIER_DISCOUNTS.standard, 0);
});

test('validateCustomer accepts valid customer', () => {
  const result = validateCustomer({ id: 'C-100', name: 'Test Co', email: 'test@example.com' });

  assert.equal(result.ok, true);
});

test('validateCustomer rejects missing id', () => {
  const result = validateCustomer({ name: 'Test Co', email: 'test@example.com' });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_INVALID' });
});

test('validateCustomer rejects missing name', () => {
  const result = validateCustomer({ id: 'C-100', email: 'test@example.com' });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_INVALID' });
});

test('validateCustomer rejects invalid email', () => {
  const result = validateCustomer({ id: 'C-100', name: 'Test Co', email: 'not-an-email' });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_INVALID' });
});

test('mergeCustomers moves invoices from one customer to another', () => {
  const customers = listCustomers();
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ sku: 'DEV-HOUR', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-002',
      issueDate: '2026-10-10',
      dueDate: '2026-11-09',
      status: 'issued',
      lines: [{ sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
    },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.find((c) => c.id === 'C-001'), undefined);
  assert.equal(result.value.invoices.filter((inv) => inv.customerId === 'C-002').length, 2);
  assert.equal(result.value.invoices.filter((inv) => inv.customerId === 'C-001').length, 0);
});

test('mergeCustomers normalizes customer ids', () => {
  const customers = listCustomers();
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ sku: 'DEV-HOUR', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
    },
  ];

  const result = mergeCustomers(customers, invoices, 'c-001 ', ' C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers returns SAME_CUSTOMER error when merging with self', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-001');

  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers returns SAME_CUSTOMER error when merging normalized same customer', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'c-001 ', ' C-001');

  assert.deepEqual(result, { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers returns CUSTOMER_NOT_FOUND when fromId not found', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'UNKNOWN', 'C-001');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers returns CUSTOMER_NOT_FOUND when intoId not found', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'UNKNOWN');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers returns CUSTOMER_NOT_FOUND when both not found', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'UNKNOWN1', 'UNKNOWN2');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers does not mutate original customers array', () => {
  const customers = listCustomers();
  const originalLength = customers.length;
  const originalFirstCustomer = customers[0];
  const invoices = [];

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(customers.length, originalLength);
  assert.deepEqual(customers[0], originalFirstCustomer);
});

test('mergeCustomers does not mutate original invoices array', () => {
  const customers = listCustomers();
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ sku: 'DEV-HOUR', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
    },
  ];
  const originalCustomerId = invoices[0].customerId;

  mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(invoices[0].customerId, originalCustomerId);
});

test('mergeCustomers preserves other customers invoices', () => {
  const customers = listCustomers();
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ sku: 'DEV-HOUR', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-003',
      issueDate: '2026-10-10',
      dueDate: '2026-11-09',
      status: 'issued',
      lines: [{ sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
    },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.value.invoices.find((inv) => inv.customerId === 'C-003'), result.value.invoices[1]);
});

test('mergeCustomers with multiple invoices for fromId', () => {
  const customers = listCustomers();
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ sku: 'DEV-HOUR', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
    },
    {
      number: 'INV-2026-0002',
      customerId: 'C-001',
      issueDate: '2026-10-15',
      dueDate: '2026-11-14',
      status: 'issued',
      lines: [{ sku: 'DEV-HOUR', qty: 8, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
    },
    {
      number: 'INV-2026-0003',
      customerId: 'C-002',
      issueDate: '2026-10-20',
      dueDate: '2026-11-19',
      status: 'issued',
      lines: [{ sku: 'DEV-HOUR', qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
    },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  const c001Invoices = result.value.invoices.filter((inv) => inv.customerId === 'C-001');
  const c002Invoices = result.value.invoices.filter((inv) => inv.customerId === 'C-002');
  assert.equal(c001Invoices.length, 0);
  assert.equal(c002Invoices.length, 3);
});

test('mergeCustomers with no invoices for fromId', () => {
  const customers = listCustomers();
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-002',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'issued',
      lines: [{ sku: 'DEV-HOUR', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 0 }],
    },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.customers.find((c) => c.id === 'C-001'), undefined);
  assert.equal(result.value.invoices.length, 1);
});

test('mergeCustomers preserves invoice lines and payments', () => {
  const customers = listCustomers();
  const invoices = [
    {
      number: 'INV-2026-0001',
      customerId: 'C-001',
      issueDate: '2026-10-07',
      dueDate: '2026-11-06',
      status: 'partially_paid',
      lines: [
        { sku: 'DEV-HOUR', qty: 10, unitPrice: 9500, vatRate: 21, discountPercent: 5 },
        { sku: 'DESIGN-HOUR', qty: 5, unitPrice: 12000, vatRate: 21, discountPercent: 0 },
      ],
      payments: [{ amount: 50000, date: '2026-10-15' }],
    },
  ];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].lines.length, 2);
  assert.equal(result.value.invoices[0].payments.length, 1);
  assert.equal(result.value.invoices[0].payments[0].amount, 50000);
});

test('mergeCustomers with empty invoices array', () => {
  const customers = listCustomers();
  const invoices = [];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');

  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert(!result.value.customers.find((c) => c.id === 'C-001'));
});

test('mergeCustomers removes exactly one customer', () => {
