import test from 'node:test';
import assert from 'node:assert/strict';
import { getCustomer, listCustomers, normalizeId, validateCustomer, mergeCustomers, TIER_DISCOUNTS } from '../src/customers.js';

test('getCustomer returns customer by id', () => {
  const result = getCustomer('C-001');

  assert.equal(result.ok, true);
  assert.equal(result.value.id, 'C-001');
  assert.equal(result.value.name, 'Northwind Studio');
});

test('getCustomer normalizes id', () => {
  const result1 = getCustomer('c-001');
  const result2 = getCustomer('C-001 ');

  assert.equal(result1.ok, true);
  assert.equal(result1.value.id, 'C-001');
  assert.equal(result2.ok, true);
  assert.equal(result2.value.id, 'C-001');
});

test('getCustomer returns CUSTOMER_NOT_FOUND for unknown id', () => {
  const result = getCustomer('UNKNOWN');

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('getCustomer does not mutate the customer record', () => {
  const result = getCustomer('C-001');
  result.value.name = 'Modified';

  const result2 = getCustomer('C-001');
  assert.equal(result2.value.name, 'Northwind Studio');
});

test('listCustomers returns all customers', () => {
  const customers = listCustomers();

  assert(Array.isArray(customers));
  assert(customers.length > 0);
  assert(customers.some((c) => c.id === 'C-001'));
});

test('listCustomers does not mutate original data', () => {
  const customers1 = listCustomers();
  customers1[0].name = 'Modified';

  const customers2 = listCustomers();
  assert.equal(customers2[0].name, 'Northwind Studio');
});

test('normalizeId trims and uppercases', () => {
  assert.equal(normalizeId('c-001'), 'C-001');
  assert.equal(normalizeId('C-001 '), 'C-001');
  assert.equal(normalizeId(' c-001 '), 'C-001');
  assert.equal(normalizeId('  C-001  '), 'C-001');
});

test('TIER_DISCOUNTS has expected values', () => {
  assert.equal(TIER_DISCOUNTS.gold, 5);
  assert.equal(TIER_DISCOUNTS.silver, 2.5);
  assert.equal(TIER_DISCOUNTS.standard, 0);
});

test('validateCustomer accepts valid customer', () => {
  const result = validateCustomer({ id: 'C-100', name: 'Test Co', email: 'test@example.com' });

  assert.equal(result.ok, true);
});

test('validateCustomer rejects missing id', () => {
  const result = validateCustomer({ name: 'Test Co', email: 'test@example.com' });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_INVALID' });
});

test('validateCustomer rejects missing name', () => {
  const result = validateCustomer({ id: 'C-100', email: 'test@example.com' });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_INVALID' });
});

test('validateCustomer rejects invalid email', () => {
  const result = validateCustomer({ id: 'C-100', name: 'Test Co', email: 'not-an-email' });

  assert.deepEqual(result, { ok: false, error: 'CUSTOMER_INVALID' });
});

