import { readFileSync } from 'node:fs';
import { ok, fail } from './result.js';

const CUSTOMERS = JSON.parse(readFileSync(new URL('../data/customers.json', import.meta.url), 'utf8'));

export const TIER_DISCOUNTS = {
  gold: 5,
  silver: 2.5,
  standard: 0,
};

export function normalizeId(id) {
  return String(id).trim().toUpperCase();
}

/**
 * All customers: { id, name, email, country, tier }.
 */
export function listCustomers() {
  return CUSTOMERS.map((c) => ({ ...c }));
}

/**
 * One customer by id.
 * @param {string} id
 */
export function getCustomer(id) {
  const normalizedId = normalizeId(id);
  const c = CUSTOMERS.find((x) => x.id === normalizedId);
  return c ? ok({ ...c }) : fail('CUSTOMER_NOT_FOUND');
}

/**
 * Check a customer record before it is stored.
 * @param {{ id?: string, name?: string, email?: string }} c
 */
export function validateCustomer(c) {
  if (!c || !c.id || !c.name || !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(c.email ?? '')) return fail('CUSTOMER_INVALID');
  return ok({ ...c });
}

/**
 * Merge two customers: move all invoices from fromId to intoId and remove fromId.
 * @param {Array} customers
 * @param {Array} invoices
 * @param {string} fromId
 * @param {string} intoId
 * @returns {{ ok: true, value: { customers: Array, invoices: Array } } | { ok: false, error: string }}
 */
export function mergeCustomers(customers, invoices, fromId, intoId) {
  const normalizedFromId = normalizeId(fromId);
  const normalizedIntoId = normalizeId(intoId);

  if (normalizedFromId === normalizedIntoId) {
    return fail('SAME_CUSTOMER');
  }

  const fromExists = customers.some((c) => c.id === normalizedFromId);
  const intoExists = customers.some((c) => c.id === normalizedIntoId);

  if (!fromExists || !intoExists) {
    return fail('CUSTOMER_NOT_FOUND');
  }

  const newCustomers = customers.filter((c) => c.id !== normalizedFromId).map((c) => ({ ...c }));

  const newInvoices = invoices.map((inv) => ({
    ...inv,
    customerId: inv.customerId === normalizedFromId ? normalizedIntoId : inv.customerId,
    lines: inv.lines?.map((line) => ({ ...line })) ?? [],
    payments: inv.payments?.map((payment) => ({ ...payment })) ?? [],
  }));

  return ok({ customers: newCustomers, invoices: newInvoices });
}
